<?php
declare(strict_types=1);
require dirname(__DIR__).'/src/Config.php'; require dirname(__DIR__).'/src/Database/Connection.php';
\DndPortal\Config::loadDotEnv(dirname(__DIR__).'/.env');
if(\DndPortal\Config::env('APP_ENV')!=='preview'||\DndPortal\Config::env('DB_NAME')!=='dnd_portal_v4_preview')die("Refused: V4 preview database required.\n");
$db=\DndPortal\Database\Connection::make();$db->beginTransaction();
try{$role=function(string $k)use($db){$q=$db->prepare('SELECT id FROM roles WHERE role_key=?');$q->execute([$k]);return(int)$q->fetchColumn();};$make=function(string $prefix,string $roleKey)use($db,$role){$u=\DndPortal\Config::env($prefix.'_USERNAME');$e=\DndPortal\Config::env($prefix.'_EMAIL');$p=\DndPortal\Config::env($prefix.'_PASSWORD');$n=\DndPortal\Config::env($prefix.'_DISPLAY_NAME',$u);if($u===''||$e===''||$p==='')return null;$q=$db->prepare('SELECT id FROM users WHERE username=? OR email=?');$q->execute([$u,$e]);$id=$q->fetchColumn();if($id===false){$db->prepare('INSERT INTO users(display_name,email,username,account_status) VALUES(?,?,?,"active")')->execute([$n,$e,$u]);$id=$db->lastInsertId();$db->prepare('INSERT INTO user_credentials(user_id,password_hash,password_algo) VALUES(?,?,?)')->execute([$id,password_hash($p,PASSWORD_DEFAULT),PASSWORD_DEFAULT]);}$db->prepare('INSERT IGNORE INTO user_roles(user_id,role_id) VALUES(?,?)')->execute([$id,$role($roleKey)]);return(int)$id;};$admin=$make('TESTADMIN','portal_admin');$make('TESTUSER','campaign_member');$make('TESTDM','campaign_dm');if($admin===null)throw new RuntimeException('TESTADMIN configuration is required for preview seed');$q=$db->query("SELECT id FROM global_polls WHERE title='Preview global poll'");if($q->fetchColumn()===false){$db->prepare('INSERT INTO global_polls(title,explanation,choice_type,status,created_by) VALUES("Preview global poll","Preview poll","single","open",?)')->execute([$admin]);$id=$db->lastInsertId();$o=$db->prepare('INSERT INTO global_poll_options(poll_id,label,position) VALUES(?,?,?)');foreach(['Thursday','Friday'] as $i=>$label)$o->execute([$id,$label,$i+1]);}$q=$db->prepare('SELECT id FROM users WHERE account_status="invited" AND email IS NULL LIMIT 1');$q->execute();$pending=$q->fetchColumn();if($pending===false){$db->prepare('INSERT INTO users(display_name,account_status) VALUES("Preview pending","invited")')->execute([]);$pending=$db->lastInsertId();}$invite=$db->prepare('INSERT IGNORE INTO registration_invites(invited_user_id,code_hash,created_by,expires_at) VALUES(?,?,?,DATE_ADD(UTC_TIMESTAMP(),INTERVAL 30 DAY))');$invite->execute([$pending,hash('sha256','PREVIEW-TYPE-A',true),$admin]);$invite->execute([null,hash('sha256','PREVIEW-TYPE-B',true),$admin]);$db->commit();echo "SEEDED V4 preview\n";}catch(Throwable $e){if($db->inTransaction())$db->rollBack();fwrite(STDERR,$e->getMessage()."\n");exit(1);}
